{"source_files":{"producer.py":"import json
import os
from datetime import datetime
from models import SensorReading


def serialize_event(event: SensorReading) -> str:
    """
    Serialize a SensorReading to a JSON string.
    Ensures the measured_at timestamp is formatted with 'T' between date and time (ISO 8601).
    """
    if isinstance(event.measured_at, datetime):
        measured_at_str = event.measured_at.isoformat()
    else:
        measured_at_str = str(event.measured_at)
        # Ensure no space in timestamp; replace space with 'T' if needed
        if " " in measured_at_str:
            measured_at_str = measured_at_str.replace(" ", "T")

    data = {
        "reading_id": event.reading_id,
        "measured_at": measured_at_str,
        "sensor_name": event.sensor_name,
        "metric_type": event.metric_type,
        "location": event.location,
    }

    return json.dumps(data, ensure_ascii=False)


def produce_events(events: list[SensorReading], output_path: str) -> None:
    """
    Produce UTF-8 JSON Lines: one complete event object per input event, in order.
    """
    with open(output_path, "w", encoding="utf-8") as f:
        for event in events:
            f.write(serialize_event(event) + "\n")
